// Каталог основного набора алертов (70 наборов × 3 стиля). Сгенерирован из config.json набора Crossember-Alerts.
// Картинки слоёв лежат в resources/alertpack/<набор>/*.webp и входят в программу. Анимация собирается в оверлее
// из слоёв по ключевым кадрам набора — с частотой экрана, а не готовым роликом.
// Модуль без node-импортов: его используют и ядро, и рендерер.

export type PackMode = 'classic' | 'corner' | 'icon'
export const PACK_MODES: { id: PackMode; name: string }[] = [
  { id: 'classic', name: 'Стандартный' },
  { id: 'icon', name: 'Альтернативный' },
  { id: 'corner', name: 'Угловой BETA' }
]
/** Слои набора (файлы <слой>.webp). Порядок — порядок отрисовки. */
export const PACK_LAYERS = ['frame', 'sled', 'hero', 'action', 'icon', 'fx-1', 'fx-2', 'fx-3', 'snow'] as const
export type PackLayer = (typeof PACK_LAYERS)[number]
export const PACK_LAYER_NAME: Record<PackLayer, string> = {
  frame: 'Рамка', sled: 'Санки', hero: 'Персонаж', action: 'Персонаж в движении', icon: 'Значок', 'fx-1': 'Эффект 1', 'fx-2': 'Эффект 2', 'fx-3': 'Эффект 3', snow: 'Снег'
}
/** Размер слоя на холсте (без масштаба ключей). */
export const PACK_LAYER_SIZE: Record<PackLayer, [number, number]> = {
  frame: [1200, 400], sled: [386, 103], hero: [340, 340], action: [340, 340], icon: [154, 154], 'fx-1': [72, 72], 'fx-2': [72, 72], 'fx-3': [72, 72], snow: [138, 138]
}

type Ease = 'linear' | 'ease' | 'in' | 'out' | 'inout'
/** Ключ слоя: время, мс; x, y на холсте; масштаб; поворот; прозрачность; плавность. */
export type PackLayerKey = [number, number, number, number, number, number, Ease]
/** Ключ текста: время, мс; смещение x, y; масштаб; прозрачность; плавность. */
export type PackTextKey = [number, number, number, number, number, Ease]
export interface PackScene {
  ms: number
  layers: [PackLayer, PackLayerKey[]][]
  text: PackTextKey[]
  /** Проявление рамки: вид, начало, длина (мс). */
  reveal: ['right' | 'down' | 'circle', number, number] | null
}
export interface PackSet {
  id: string
  name: string
  category: string
  style: string
  action: string
  color: string
  /** Цвет суммы (второй цвет палитры набора). */
  accent: string
  font: 'manrope' | 'unbounded'
  /** Область текста в координатах сцены 1400×620 (сцена стоит в X=260, Y=230): x, y, ширина, высота. */
  safe: [number, number, number, number]
  /** «Углового» здесь нет: его сцены лежат в resources/alertpack/<набор>/corner/scene.json (см. CornerScene). */
  modes: Record<Exclude<PackMode, 'corner'>, PackScene>
}

export const PACK_CATEGORIES: string[] = ["Уютные и милые", "Игровые", "Фэнтези и магия", "Космос и Sci-Fi", "Еда", "Сезонные и праздничные", "Стили и жанры", "Музыка и движение"]

type SceneRow = [number, PackScene['layers'], PackTextKey[], PackScene['reveal']]
type Row = [string, string, number, string, string, string, string, PackSet['font'], PackSet['safe'], SceneRow[]]
