const scene = ([ms, layers, text, reveal]: SceneRow): PackScene => ({ ms, layers, text, reveal })
export const PACK_SETS: PackSet[] = ROWS.map(([id, name, cat, style, action, color, accent, font, safe, m]) => ({
  id, name, category: PACK_CATEGORIES[cat], style, action, color, accent, font, safe,
  modes: { classic: scene(m[0]), icon: scene(m[1]) }
}))

const IDS: ReadonlySet<string> = new Set(PACK_SETS.map((s) => s.id))
export const packHas = (id: string): boolean => IDS.has(id)

/** Положения угловой сцены (ключи positions в corner/scene.json). */
export const CORNER_POSITIONS = ['top-left', 'top-center', 'top-right', 'bottom-left', 'bottom-center', 'bottom-right'] as const
export type CornerPosition = (typeof CORNER_POSITIONS)[number]
export const CORNER_POSITION_NAME: Record<CornerPosition, string> = {
  'top-left': 'Сверху слева', 'top-center': 'Сверху по центру', 'top-right': 'Сверху справа',
  'bottom-left': 'Снизу слева', 'bottom-center': 'Снизу по центру', 'bottom-right': 'Снизу справа'
}
type CornerEase = 'linear' | 'ease' | 'in' | 'out' | 'inout' | 'back'
export interface CornerKey { t: number; x: number; y: number; scale: number; rotate: number; opacity: number; ease: CornerEase }
/** Одно положение из corner/scene.json: слои снизу вверх, file — от папки corner/, ключи слоя — от его начала. */
export interface CornerScene {
  durationMs: number
  layers: { name: string; file: string; x: number; y: number; w: number; h: number; start: number; duration: number; keyframes: CornerKey[]; wipe: 'none' | 'right' | 'down' | 'circle'; wipeStart: number; wipeMs: number }[]
  /** Текст: area — где он читается; ключи — смещение от area, время от начала алерта; insertAfter — после скольких слоёв. */
  text: { area: { x: number; y: number; w: number; h: number }; color: string; accent: string; insertAfter: number; keyframes: CornerKey[] }
}
export interface CornerFile { id: string; positions: Record<CornerPosition, CornerScene> }

/**
 * Id слоя: «p:<набор>/<слой>.webp» или «p:<набор>/corner/(parts|hero)/<файл>.(webp|png)».
 * Путь на сервере оверлеев или '' если id чужой. Файлы угловых сцен сервер дополнительно ищет на диске.
 */
export function packPath(media: string): string {
  const m = /^p:([0-9]{2}-[a-z0-9-]{1,60})\/([a-z0-9-]+)\.webp$/.exec(media)
  if (m) return IDS.has(m[1]) && (PACK_LAYERS as readonly string[]).includes(m[2]) ? `/p/${m[1]}/${m[2]}.webp` : ''
  const c = /^p:([0-9]{2}-[a-z0-9-]{1,60})\/corner\/(parts|hero)\/([a-z0-9-]{1,40}\.(webp|png))$/.exec(media)
  return c && IDS.has(c[1]) ? `/p/${c[1]}/corner/${c[2]}/${c[3]}` : ''
}
